import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0010: 为什么 Dashboard 默认关闭","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0010-why-dashboard-off-by-default.md","filePath":"zh/adr/ADR-0010-why-dashboard-off-by-default.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0010-why-dashboard-off-by-default.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0010-为什么-dashboard-默认关闭" tabindex="-1">ADR-0010: 为什么 Dashboard 默认关闭 <a class="header-anchor" href="#adr-0010-为什么-dashboard-默认关闭" aria-label="Permalink to “ADR-0010: 为什么 Dashboard 默认关闭”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：docs/guide/dashboard-cli-config.md §9/§10，roadmap P4</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>Dashboard 是管理面：能看到全部资源健康、能触发恢复操作。一个默认监听端口的 自愈引擎等于在每台目标机器上开一个常驻管理入口——这正是自愈系统最不该有的 攻击面。P0/P1 的目标（核心恢复闭环）完全不需要 UI。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>Dashboard 是<strong>默认关闭</strong>的可选组件：不启用则零监听端口、零 HTTP 代码路径 （验收：关闭时无端口、不可用不影响核心、不绕过 Core Engine、高风险仍走 统一授权审计）。启用前，HTTP 传输安全（认证、CSRF、绑定地址、只读语义） 必须集中硬化（与 ADR-0015 工具箱的传输安全同一处）。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>默认开启</strong>：每台机器常开管理面；家庭/路由器部署（OpenWrt）尤其危险。</li><li><strong>只做 CLI 不做 Dashboard</strong>：CLI 已覆盖 status/runs/incidents/notify/graph； UI 推迟不损失核心能力。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：默认部署零新增攻击面；核心保持无头、可嵌入；UI 迭代不触碰恢复语义。 缺点：前期可视性依赖 CLI；运维上手需要读文档。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>P4 的所有 Dashboard 条目都以&quot;默认关闭&quot;为前提验收。</li><li>操作授权界面（P4）复用核心的授权审计，不自建权限模型。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};